"""Apply the heading bootstrap fix, back up originals, and run Linux tests."""
import base64
from datetime import datetime
import hashlib
import json
from pathlib import Path
import runpy
import shutil
import subprocess
import sys
import zlib

PAYLOAD = ''
payload = json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))
project = Path('/home/kailash/ros2_ws/src/baseline_measurement')
for name, content in payload['files'].items():
    compile(content, name, 'exec')
for name, expected in payload['expected'].items():
    target = project / name
    current = target.read_bytes()
    new = payload['files'][name].encode()
    if hashlib.sha256(current).hexdigest() not in (expected, hashlib.sha256(new).hexdigest()):
        raise RuntimeError('Source changed since inspection: ' + name)
backup = project / 'heading_fix_backups' / datetime.now().strftime('%Y%m%d_%H%M%S')
for name, content in payload['files'].items():
    target = project / name
    target.parent.mkdir(parents=True, exist_ok=True)
    if target.exists():
        saved = backup / name
        saved.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(target, saved)
    target.write_text(content, encoding='utf-8')
print('Source updated; originals backed up at ' + str(backup), flush=True)
sys.path.insert(0, str(project))
runpy.run_path(str(project / 'tools/vscode_test_runner.py'), run_name='__main__')
directory = project / 'test-output'
with (directory / 'heading_fix_build.log').open('w') as log:
    build = subprocess.run(['colcon', 'build', '--packages-select', 'baseline_measurement'],
                           cwd='/home/kailash/ros2_ws', stdout=log,
                           stderr=subprocess.STDOUT, check=False)
(directory / 'heading_fix_build.json').write_text(json.dumps({'exit_code': build.returncode}))
print('colcon build exit code: ' + str(build.returncode), flush=True)
if build.returncode:
    print((directory / 'heading_fix_build.log').read_text(), flush=True)
    raise SystemExit(build.returncode)
